import{_ as f,C as r,o as t,c as s,a2 as e,b as o,w as d,a as n,E as l,a3 as h}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"LiteShield XDP","description":"Free, minimal XDP (eBPF) firewall for Linux 5.15+. One XDP program, one Go binary, one YAML config — per-IP rate limiting, auto-ban, live TUI, Discord alerts.","frontmatter":{"title":"LiteShield XDP","description":"Free, minimal XDP (eBPF) firewall for Linux 5.15+. One XDP program, one Go binary, one YAML config — per-IP rate limiting, auto-ban, live TUI, Discord alerts.","head":[["meta",{"name":"og:title","content":"LiteShield XDP — Minimal eBPF Firewall"}],["meta",{"name":"og:description","content":"Per-source-IP rate limits, auto-ban, whitelist/blacklist, live status TUI, Discord webhook alerts. Free and MIT-licensed."}]]},"headers":[],"relativePath":"liteshield-xdp/index.md","filePath":"liteshield-xdp/index.md","lastUpdated":1787470737000}'),v={name:"liteshield-xdp/index.md"};function c(p,a,u,b,g,P){const i=r("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e(`<h1 id="liteshield-xdp" tabindex="-1" data-v-6f02806f>LiteShield XDP <a class="header-anchor" href="#liteshield-xdp" aria-label="Permalink to &quot;LiteShield XDP&quot;" data-v-6f02806f>​</a></h1><p data-v-6f02806f><strong data-v-6f02806f>Free, minimal XDP (eBPF) firewall for Linux 5.15+</strong> — one XDP program, one Go binary, one YAML config.</p><p data-v-6f02806f>LiteShield sits at the earliest possible point in the Linux networking stack and drops floods before they ever reach your applications. No license server, no daemons, no frameworks — a lightweight alternative to heavier commercial shields that you can read end‑to‑end in an evening and trust in production the same night.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-6f02806f><p data-v-6f02806f><strong data-v-6f02806f>🛡️ Built for ALTIS TECH SOLUTIONS by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-6f02806f>AnAverageBeing</a></strong><br data-v-6f02806f><a href="https://github.com/AnAverageBeing/LiteShield-XDP" target="_blank" rel="noreferrer" data-v-6f02806f>GitHub Repo</a> · <code data-v-6f02806f>MIT License</code></p></div><hr data-v-6f02806f><h2 id="why-liteshield-xdp" tabindex="-1" data-v-6f02806f>Why LiteShield XDP? <a class="header-anchor" href="#why-liteshield-xdp" aria-label="Permalink to &quot;Why LiteShield XDP?&quot;" data-v-6f02806f>​</a></h2><p data-v-6f02806f>DDoS mitigation usually means one of two extremes: iptables rules that melt under load, or commercial appliances that cost more than the server they protect. LiteShield fills the gap:</p><table tabindex="0" data-v-6f02806f><thead data-v-6f02806f><tr data-v-6f02806f><th data-v-6f02806f>Approach</th><th data-v-6f02806f>Pain Point</th></tr></thead><tbody data-v-6f02806f><tr data-v-6f02806f><td data-v-6f02806f><strong data-v-6f02806f>iptables / nftables</strong></td><td data-v-6f02806f>Rules evaluated late in the stack; conntrack exhaustion under SYN floods</td></tr><tr data-v-6f02806f><td data-v-6f02806f><strong data-v-6f02806f>Cloud scrubbing services</strong></td><td data-v-6f02806f>Expensive, adds latency, your traffic leaves your network</td></tr><tr data-v-6f02806f><td data-v-6f02806f><strong data-v-6f02806f>Commercial XDP shields</strong></td><td data-v-6f02806f>License servers, HWID locking, closed source, heavyweight dashboards</td></tr><tr data-v-6f02806f><td data-v-6f02806f><strong data-v-6f02806f>Hand-rolled eBPF</strong></td><td data-v-6f02806f>Weeks of verifier wrestling before you drop a single packet</td></tr></tbody></table><p data-v-6f02806f>LiteShield gives you a <strong data-v-6f02806f>single statically-built Go binary</strong>, a <strong data-v-6f02806f>single verified XDP program</strong>, and a <strong data-v-6f02806f>single YAML file</strong> — production-ready in under a minute.</p><hr data-v-6f02806f><h2 id="key-features" tabindex="-1" data-v-6f02806f>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-6f02806f>​</a></h2><h3 id="⚡-single-xdp-program" tabindex="-1" data-v-6f02806f>⚡ Single XDP Program <a class="header-anchor" href="#⚡-single-xdp-program" aria-label="Permalink to &quot;⚡ Single XDP Program&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>No tail calls, no <code data-v-6f02806f>freplace</code>, no module loading. One program that verifies and attaches on any kernel 5.15+ with BTF. If the kernel accepts it, it runs — nothing to feature-gate.</p><h3 id="🌐-protects-all-ports-protocols" tabindex="-1" data-v-6f02806f>🌐 Protects All Ports &amp; Protocols <a class="header-anchor" href="#🌐-protects-all-ports-protocols" aria-label="Permalink to &quot;🌐 Protects All Ports &amp; Protocols&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>TCP, UDP, ICMP and ICMPv6, over both IPv4 and IPv6. Every packet on the interface is inspected at driver level.</p><h3 id="🚦-rule-based-flood-protection" tabindex="-1" data-v-6f02806f>🚦 Rule-Based Flood Protection <a class="header-anchor" href="#🚦-rule-based-flood-protection" aria-label="Permalink to &quot;🚦 Rule-Based Flood Protection&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>Per-source-IP, per-second thresholds for total PPS, TCP SYN rate, UDP rate, and ICMP rate — plus a global new-source-IPs/sec limit to blunt spoofed-source floods.</p><h3 id="🔨-automatic-banning" tabindex="-1" data-v-6f02806f>🔨 Automatic Banning <a class="header-anchor" href="#🔨-automatic-banning" aria-label="Permalink to &quot;🔨 Automatic Banning&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>Sources that exceed a threshold are auto-banned for a configurable duration. Bans use <code data-v-6f02806f>CLOCK_MONOTONIC</code> deadlines — the same clock the BPF program reads — so expiry is exact.</p><h3 id="📋-live-whitelist-blacklist" tabindex="-1" data-v-6f02806f>📋 Live Whitelist / Blacklist <a class="header-anchor" href="#📋-live-whitelist-blacklist" aria-label="Permalink to &quot;📋 Live Whitelist / Blacklist&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>HASH maps for IPv4 and IPv6, managed from the CLI without reloading the program:</p><div class="language-bash vp-adaptive-theme" data-v-6f02806f><button title="Copy Code" class="copy" data-v-6f02806f></button><span class="lang" data-v-6f02806f>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-6f02806f><code data-v-6f02806f><span class="line" data-v-6f02806f><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-6f02806f>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> whitelist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> 10.0.0.0/24</span></span>
<span class="line" data-v-6f02806f><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-6f02806f>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> blacklist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-6f02806f> 203.0.113.7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-6f02806f> 3600</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-6f02806f>   # 1-hour ban</span></span></code></pre></div><h3 id="🖥️-built-in-live-status-screen" tabindex="-1" data-v-6f02806f>🖥️ Built-In Live Status Screen <a class="header-anchor" href="#🖥️-built-in-live-status-screen" aria-label="Permalink to &quot;🖥️ Built-In Live Status Screen&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>A plain-text ANSI TUI with zero dependencies (no bubbletea, no lipgloss): interface, PPS, BPS, passed/dropped, active bans, uptime — refreshed every second.</p><h3 id="💬-discord-webhook-alerts" tabindex="-1" data-v-6f02806f>💬 Discord Webhook Alerts <a class="header-anchor" href="#💬-discord-webhook-alerts" aria-label="Permalink to &quot;💬 Discord Webhook Alerts&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>Simple embeds for <code data-v-6f02806f>rule_trigger</code>, <code data-v-6f02806f>ip_banned</code> and <code data-v-6f02806f>new_source</code> events, with per-event cooldowns so a flood doesn&#39;t flood your channel.</p><h3 id="🔄-hot-reloadable-config" tabindex="-1" data-v-6f02806f>🔄 Hot-Reloadable Config <a class="header-anchor" href="#🔄-hot-reloadable-config" aria-label="Permalink to &quot;🔄 Hot-Reloadable Config&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f><code data-v-6f02806f>liteshield config</code> opens the YAML in your <code data-v-6f02806f>$EDITOR</code> and applies the new thresholds to the running instance — no detach, no gap in protection.</p><h3 id="🚀-installs-in-under-a-minute" tabindex="-1" data-v-6f02806f>🚀 Installs in Under a Minute <a class="header-anchor" href="#🚀-installs-in-under-a-minute" aria-label="Permalink to &quot;🚀 Installs in Under a Minute&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>Interactive installer with deployment presets (Personal / Hosting / Enterprise), traffic profiles (Strict / Balanced / High), automatic dependency installation across six package managers, and systemd integration.</p><h3 id="🛟-fail-open-by-design" tabindex="-1" data-v-6f02806f>🛟 Fail-Open by Design <a class="header-anchor" href="#🛟-fail-open-by-design" aria-label="Permalink to &quot;🛟 Fail-Open by Design&quot;" data-v-6f02806f>​</a></h3><p data-v-6f02806f>If a map is missing, full, or an LRU race is lost, the packet <strong data-v-6f02806f>passes</strong>. LiteShield protects your link — it never takes it down.</p><hr data-v-6f02806f><h2 id="quick-install" tabindex="-1" data-v-6f02806f>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-6f02806f>​</a></h2><div class="language-bash vp-adaptive-theme" data-v-6f02806f><button title="Copy Code" class="copy" data-v-6f02806f></button><span class="lang" data-v-6f02806f>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-6f02806f><code data-v-6f02806f><span class="line" data-v-6f02806f><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-6f02806f>curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-6f02806f> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> https://raw.githubusercontent.com/AnAverageBeing/LiteShield-XDP/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" data-v-6f02806f> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-6f02806f> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-6f02806f> bash</span></span></code></pre></div><p data-v-6f02806f>The installer asks four questions (interface, preset, traffic profile, Discord webhook), builds the BPF object and Go binary, and installs to <code data-v-6f02806f>/opt/liteshield</code> with a systemd service. See <a href="./getting-started/installation" data-v-6f02806f>Installation</a> for the full walkthrough and manual install.</p><hr data-v-6f02806f><h2 id="architecture" tabindex="-1" data-v-6f02806f>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-6f02806f>​</a></h2>`,38)),(t(),o(h,null,{default:d(()=>[l(i,{id:"mermaid-147",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20NET%5B%22Inbound%20Packets%3Cbr%2F%3E(NIC%20driver)%22%5D%20--%3E%20XDP%5B%22liteshield_xdp%3Cbr%2F%3ESEC(xdp)%22%5D%0A%20%20%20%20XDP%20--%3E%20PARSE%5B%22L2%2FL3%2FL4%20Parser%3Cbr%2F%3EEthernet%20%C2%B7%20VLAN%20%C2%B7%20IPv4%2FIPv6%20%C2%B7%20TCP%2FUDP%2FICMP%22%5D%0A%20%20%20%20PARSE%20--%3E%20WL%7B%22whitelist_map%3Cbr%2F%3Ehit%3F%22%7D%0A%20%20%20%20WL%20--%3E%7C%22yes%22%7C%20PASS%5B%22XDP_PASS%22%5D%0A%20%20%20%20WL%20--%3E%7C%22no%22%7C%20BL%7B%22blacklist_map%3Cbr%2F%3Eactive%20ban%3F%22%7D%0A%20%20%20%20BL%20--%3E%7C%22yes%22%7C%20DROP%5B%22XDP_DROP%22%5D%0A%20%20%20%20BL%20--%3E%7C%22no%22%7C%20RATE%5B%22Per-IP%20Rate%20Window%3Cbr%2F%3EPPS%20%C2%B7%20SYN%20%C2%B7%20UDP%20%C2%B7%20ICMP%22%5D%0A%20%20%20%20RATE%20--%3E%20NS%7B%22New%20source%3F%3Cbr%2F%3Enew_src%20limit%22%7D%0A%20%20%20%20NS%20--%3E%7C%22over%20limit%22%7C%20DROP%0A%20%20%20%20NS%20--%3E%7C%22ok%22%7C%20TH%7B%22Thresholds%3Cbr%2F%3Eexceeded%3F%22%7D%0A%20%20%20%20TH%20--%3E%7C%22yes%22%7C%20BAN%5B%22Record%20violation%3Cbr%2F%3E%2B%20auto-ban%20timer%22%5D%20--%3E%20DROP%0A%20%20%20%20TH%20--%3E%7C%22no%22%7C%20FLOW%7B%22flow_pps%20%2F%3Cbr%2F%3Eflow_bps%20exceeded%3F%22%7D%0A%20%20%20%20FLOW%20--%3E%7C%22yes%22%7C%20DROP%0A%20%20%20%20FLOW%20--%3E%7C%22no%22%7C%20PASS%0A%0A%20%20%20%20subgraph%20Userspace%5B%22Userspace%20(Go)%22%5D%0A%20%20%20%20%20%20%20%20CLI%5B%22liteshield%20CLI%22%5D%20--%3E%20MAPS%5B%22BPF%20Maps%3Cbr%2F%3E(pinned%20at%20%2Fsys%2Ffs%2Fbpf%2Fliteshield)%22%5D%0A%20%20%20%20%20%20%20%20TUI%5B%22Live%20Status%20TUI%22%5D%20--%3E%20MAPS%0A%20%20%20%20%20%20%20%20MAPS%20--%3E%20ALERTS%5B%22Discord%20Alerter%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20XDP%20-.-%3E%7C%227%20BPF%20maps%22%7C%20MAPS%0A%20%20%20%20ALERTS%20--%3E%20DISCORD%5B%22Discord%20Webhook%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="enforcement-order" tabindex="-1" data-v-6f02806f>Enforcement Order <a class="header-anchor" href="#enforcement-order" aria-label="Permalink to &quot;Enforcement Order&quot;" data-v-6f02806f>​</a></h3><table tabindex="0" data-v-6f02806f><thead data-v-6f02806f><tr data-v-6f02806f><th data-v-6f02806f>Step</th><th data-v-6f02806f>Check</th><th data-v-6f02806f>Verdict</th></tr></thead><tbody data-v-6f02806f><tr data-v-6f02806f><td data-v-6f02806f>1</td><td data-v-6f02806f>Parse L2/L3/L4</td><td data-v-6f02806f>Malformed / non-IP → pass (not our business)</td></tr><tr data-v-6f02806f><td data-v-6f02806f>2</td><td data-v-6f02806f>Whitelist</td><td data-v-6f02806f>Hit → always pass</td></tr><tr data-v-6f02806f><td data-v-6f02806f>3</td><td data-v-6f02806f>Blacklist</td><td data-v-6f02806f>Active ban (permanent or timed) → drop</td></tr><tr data-v-6f02806f><td data-v-6f02806f>4</td><td data-v-6f02806f>Global new-source limit</td><td data-v-6f02806f>Over <code data-v-6f02806f>new_src</code>/sec → drop</td></tr><tr data-v-6f02806f><td data-v-6f02806f>5</td><td data-v-6f02806f>Auto-ban timer</td><td data-v-6f02806f>Still banned → drop</td></tr><tr data-v-6f02806f><td data-v-6f02806f>6</td><td data-v-6f02806f>Per-IP thresholds</td><td data-v-6f02806f>PPS / SYN / UDP / ICMP exceeded → drop + optional auto-ban</td></tr><tr data-v-6f02806f><td data-v-6f02806f>7</td><td data-v-6f02806f>Per-flow limits</td><td data-v-6f02806f><code data-v-6f02806f>flow_pps</code> / <code data-v-6f02806f>flow_bps</code> exceeded → drop</td></tr></tbody></table><hr data-v-6f02806f><h2 id="comparison" tabindex="-1" data-v-6f02806f>Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;" data-v-6f02806f>​</a></h2><table tabindex="0" data-v-6f02806f><thead data-v-6f02806f><tr data-v-6f02806f><th data-v-6f02806f>Capability</th><th data-v-6f02806f>LiteShield XDP</th><th data-v-6f02806f>gamemann/XDP-Firewall</th><th data-v-6f02806f>OpenShield-XDP</th></tr></thead><tbody data-v-6f02806f><tr data-v-6f02806f><td data-v-6f02806f>Price</td><td data-v-6f02806f>✅ Free (MIT)</td><td data-v-6f02806f>✅ Free</td><td data-v-6f02806f>Paid</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Userspace</td><td data-v-6f02806f>Single Go binary</td><td data-v-6f02806f>C + config file</td><td data-v-6f02806f>Go + full TUI dashboard</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Live status TUI</td><td data-v-6f02806f>✅ Built-in (no deps)</td><td data-v-6f02806f>❌</td><td data-v-6f02806f>✅ 7-screen dashboard</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Discord alerts</td><td data-v-6f02806f>✅</td><td data-v-6f02806f>❌</td><td data-v-6f02806f>✅ Rich forensics embeds</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Whitelist/blacklist</td><td data-v-6f02806f>CLI, live, IPv4+IPv6</td><td data-v-6f02806f>Config file, reload</td><td data-v-6f02806f>CLI, live, CIDRs, subnet auto-ban</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Per-IP rate rules</td><td data-v-6f02806f>PPS/SYN/UDP/ICMP/new-src</td><td data-v-6f02806f>PPS/bps + filters</td><td data-v-6f02806f>42 detection vectors L2–L7</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Flow rate rules</td><td data-v-6f02806f>✅ PPS/BPS per flow</td><td data-v-6f02806f>❌</td><td data-v-6f02806f>✅</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Interactive installer</td><td data-v-6f02806f>✅ Presets</td><td data-v-6f02806f>❌</td><td data-v-6f02806f>✅ 10 profiles × 7 levels</td></tr><tr data-v-6f02806f><td data-v-6f02806f>BPF layout</td><td data-v-6f02806f>1 program, 7 maps</td><td data-v-6f02806f>1 program, many maps</td><td data-v-6f02806f>Multi-stage pipeline, freplace</td></tr><tr data-v-6f02806f><td data-v-6f02806f>Attack forensics</td><td data-v-6f02806f>❌</td><td data-v-6f02806f>❌</td><td data-v-6f02806f>✅ Per-attack reports</td></tr><tr data-v-6f02806f><td data-v-6f02806f>License system</td><td data-v-6f02806f>None</td><td data-v-6f02806f>None</td><td data-v-6f02806f>HWID-bound, Ed25519</td></tr></tbody></table><blockquote data-v-6f02806f><p data-v-6f02806f><strong data-v-6f02806f>Bottom line:</strong> LiteShield is the free baseline — embed it, fork it, ship it. If you need 42-vector detection, attack forensics, and baseline learning, step up to <a href="https://builtbybit.com/resources/openshield-xdp-ddos-protection.115692/" target="_blank" rel="noreferrer" data-v-6f02806f>OpenShield-XDP</a>.</p></blockquote><hr data-v-6f02806f><h2 id="next-steps" tabindex="-1" data-v-6f02806f>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-6f02806f>​</a></h2><ul data-v-6f02806f><li data-v-6f02806f><strong data-v-6f02806f><a href="./getting-started/installation" data-v-6f02806f>Installation →</a></strong> — Protected in under a minute.</li><li data-v-6f02806f><strong data-v-6f02806f><a href="./configuration/reference" data-v-6f02806f>Configuration Reference →</a></strong> — Every YAML value, preset, and multiplier.</li><li data-v-6f02806f><strong data-v-6f02806f><a href="./user-guide/cli" data-v-6f02806f>CLI Reference →</a></strong> — Every command, flag, and output.</li><li data-v-6f02806f><strong data-v-6f02806f><a href="./user-guide/tui" data-v-6f02806f>TUI Guide →</a></strong> — Reading the live status screen.</li><li data-v-6f02806f><strong data-v-6f02806f><a href="./architecture/overview" data-v-6f02806f>Architecture →</a></strong> — Maps, pipeline, and the fail-open design.</li></ul><hr data-v-6f02806f><div class="footer-note" data-v-6f02806f><p data-v-6f02806f><strong data-v-6f02806f>Developed by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer" data-v-6f02806f>AnAverageBeing</a> for <a href="https://github.com/pingless-studios" target="_blank" rel="noreferrer" data-v-6f02806f>ALTIS TECH SOLUTIONS</a></strong></p><p data-v-6f02806f>Crafted with ❤️ and one very opinionated <code data-v-6f02806f>XDP_DROP</code>.<br data-v-6f02806f> If this project saves you from a 3 AM flood, consider starring the repo.</p></div>',11))])}const C=f(v,[["render",c],["__scopeId","data-v-6f02806f"]]);export{k as __pageData,C as default};
